---@class CommonAdActivityConfig
local CommonAdActivityConfig = T(Global, "CommonAdActivityConfig")
---@type table<string, CommonAdActivityItemData>
local ItemConfigList = {}
---@type table<number, CommonAdActivityRewardGroup>
local RewardGroupList = {}
---@type table<number, CommonAdActivityRewardData>
local RewardList = {}
---@type uuid
local uuid = require "engine_base.util.uuid"

function CommonAdActivityConfig:init()
    local config = FileUtil.getGameConfigFromCsv("pay_activity/CommonAdActivityItem.csv")
    for _, item in pairs(config or {}) do
        ---@class CommonAdActivityItemData
        local data = {
            tag = item.tag,
            activityId = tonumber(item.activityId),
            quality = tonumber(item.quality),
            sort = tonumber(item.sort),
            image = item.image,
            action = item.action,
            hideUI = item.hideUI == "1",
            params = StringUtil.split(item.params, "#"),
            dayMaxTimes = tonumber(item.dayMaxTimes),
            coolingTime = tonumber(item.coolingTime),
            id = tonumber(item.id)
        }
        if isClient then
            local params = {}
            params.ad_type = "video"
            params.ad_game = GameType
            params.ad_uuid = uuid()
            params.ad_reward = data.params[1]
            local builder = DataBuilder.new():fromTable(params)
            GMSetting:addItem("付费活动", "看广告:" .. data.tag, "watchAd", data.id, builder:getData())
        end
        ItemConfigList[data.tag] = data
    end
    config = FileUtil.getGameConfigFromCsv("pay_activity/CommonAdActivityReward.csv")
    for _, item in pairs(config or {}) do
        ---@class CommonAdActivityRewardData
        local data = {
            id = tonumber(item.id),
            activityId = tonumber(item.activityId),
            rewardId = tonumber(item.rewardId),
            needTimes = tonumber(item.needTimes),
            maxTimes = tonumber(item.needTimes),
        }
        local group = RewardGroupList[data.activityId]
        if not group then
            ---@class CommonAdActivityRewardGroup
            ---@field rewards CommonAdActivityRewardData[]
            local new = {
                rewards = {},
                maxTimes = 0,
                sorted = false,
            }
            group = new
            RewardGroupList[data.activityId] = group
        end
        group.maxTimes = math.max(data.needTimes, group.maxTimes)
        table.insert(group.rewards, data)
        RewardList[data.id] = data
    end
end

---@return CommonAdActivityItemData[]
function CommonAdActivityConfig:getItemCfgs(activityId)
    ---@type CommonAdActivityItemData[]
    local cfgs = {}
    for _, cfg in pairs(ItemConfigList) do
        if cfg.activityId == activityId then
            table.insert(cfgs, cfg)
        end
    end
    table.sort(cfgs, function(a, b)
        return a.sort < b.sort
    end)
    return cfgs
end

function CommonAdActivityConfig:getRewardGroup(activityId)
    local group = RewardGroupList[activityId]
    if not group then
        return
    end
    if not group.sorted then
        table.sort(group.rewards, function(a, b)
            return a.needTimes < b.needTimes
        end)
        group.sorted = true
    end
    return group
end

---@return CommonAdActivityRewardData
function CommonAdActivityConfig:getRewardById(id)
    return RewardList[id]
end

---@return CommonAdActivityItemData
function CommonAdActivityConfig:getCfgByTag(tag)
    return ItemConfigList[tag]
end

---@return CommonAdActivityItemData
function CommonAdActivityConfig:getItemCfgById(id)
    for _, cfg in pairs(ItemConfigList) do
        if cfg.id == id then
            return cfg
        end
    end
    return false
end

CommonAdActivityConfig:init()

return CommonAdActivityConfig